effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmHash1(float n){ return fract(sin(n) * 43758.5453123); }
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec2 sz = getTexSize(inputImg.size);
float frame = floor(acTime * 18.0);
float l = gmLum(src.rgb);
vec3 sep = mix(darkBrown.rgb, lightCream.rgb, clamp(l, 0.0, 1.0));
sep = mix(sep, sep * vec3(1.06, 0.98, 0.82) + vec3(0.03, 0.015, 0.0), sepiaWarm);
float fl = 1.0 - reelFlicker * 0.10 * (gmHash1(frame) - 0.5 + 0.05 * sin(acTime * 29.0));
sep *= fl;
if (dustAmt > 0.001) {
float d = gmHash2(floor(uv * sz * 0.4) + frame * 7.3);
sep = mix(sep, vec3(0.93, 0.88, 0.78), step(0.9985 + dustAmt * 0.0035 - 0.0035, d) * dustAmt * 0.6);
}
if (scratchAmt > 0.001) {
float col = floor(uv.x * sz.x);
float active = step(0.9993 - scratchAmt * 0.002, gmHash1(col * 1.3 + floor(frame / 12.0)));
float lineW = 0.6 / sz.x;
float line = 1.0 - smoothstep(lineW * 0.5, lineW, abs(uv.x - (col + gmHash1(col)) / sz.x));
sep += vec3(0.35) * active * line * scratchAmt;
}
sep *= 1.0 - sepiaVig * 0.8 * smoothstep(0.3, 0.88, length(uv - 0.5));
vec3 col = mix(src.rgb, clamp(sep, 0.0, 1.0), sepiaMix * 0.01);
gl_FragColor = vec4(col * src.a, src.a);
}
